    // ══════════════════════════════════════════════════════════════
    // FILM-163: CONTINUITY BOARD
    // ══════════════════════════════════════════════════════════════
    /** The served URL for a continuity photograph, keyed to the asset that holds it. */
    const MARKETING_TYPE_ICON = { poster: '&#127917;', key_art: '&#127912;', banner: '&#128444;',
        social_card: '&#128241;', still: '&#128247;', thumbnail: '&#128443;', logo: '&#10024;' };

    /** Where a marketing picture is served from — the same place plates live. */
    function marketingImgSrc(a) {
        const name = String(a.image_path || '').split('/').pop();
        return `${API_BASE}/film/refsheets/${state.currentProject.id}/${encodeURIComponent(name)}?w=480`;
    }

    async function loadMarketing() {
        if (!state.currentProject) return;
        setStatus('Loading marketing...');
        try {
            const filter = document.getElementById('marketingFilter')?.value || '';
            let url = '/projects/' + state.currentProject.id + '/marketing';
            if (filter) url += '?type=' + encodeURIComponent(filter);
            const data = await api(url);
            // The route returns `marketing_assets`. Guessing the key is how a
            // page renders an empty state over data that is actually there.
            const assets = data.marketing_assets || [];
            const el = document.getElementById('marketingGrid');

            if (!assets.length) {
                el.innerHTML = '<div class="empty-state" style="grid-column:1/-1;"><div class="icon">&#127917;</div>'
                    + '<h3>No marketing assets</h3><p>Add a poster, key art or a social card. '
                    + 'You can upload one you already made, or generate it from the film&rsquo;s own look.</p></div>';
                setStatus('No marketing assets');
                return;
            }

            el.innerHTML = assets.map(a => `
                <div class="entity-card">
                    <div class="entity-card-header">
                        <div class="entity-avatar" style="background:var(--gl-bg-elevated);">${MARKETING_TYPE_ICON[a.type] || '&#127917;'}</div>
                        <div>
                            <h3 style="font-size:13px;">${esc(a.title || 'Untitled')}</h3>
                            <p class="text-sm text-muted">${esc(String(a.type || '').replace(/_/g, ' '))} &middot; ${esc(a.aspect_ratio || '')}</p>
                        </div>
                    </div>
                    ${a.image_path
                        ? `<img src="${marketingImgSrc(a)}" alt="" style="width:100%;border-radius:6px;margin-top:8px;display:block;">`
                        : `<p class="text-sm text-muted" style="margin-top:8px;">${esc(a.prompt || 'No artwork yet.')}</p>`}
                    <div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap;align-items:center;">
                        ${uploadControl('marketing-asset', `/marketing/${a.id}/import`,
                            { extra: {}, after: 'loadMarketing',
                              label: a.image_path ? 'Replace' : 'Upload',
                              title: 'Use artwork you made in a design tool' })}
                        <button class="btn btn-secondary btn-sm" onclick="generateMarketingArt('${a.id}')">
                            ${a.image_path ? 'Regenerate' : 'Generate'}</button>
                        <button class="btn btn-danger btn-sm" onclick="deleteMarketingAsset('${a.id}')">Delete</button>
                    </div>
                </div>`).join('');
            setStatus(assets.length + ' marketing asset(s)');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function createMarketingAsset() {
        if (!state.currentProject) return;
        const body = {
            type: document.getElementById('mkType').value,
            title: document.getElementById('mkTitle').value.trim(),
            prompt: document.getElementById('mkPrompt').value.trim(),
            aspect_ratio: document.getElementById('mkAspect').value,
            resolution: document.getElementById('mkResolution').value.trim(),
        };
        if (!body.title) { setStatus('Give it a title first'); return; }
        try {
            await api('/projects/' + state.currentProject.id + '/marketing',
                { method: 'POST', body: JSON.stringify(body) });
            closeModal('marketingModal');
            document.getElementById('mkTitle').value = '';
            document.getElementById('mkPrompt').value = '';
            setStatus('Marketing asset created');
            loadMarketing();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /**
     * Generating a poster costs the same as generating a frame, so it goes
     * through a confirmation showing what would be sent — the rule every other
     * paid path in the app follows.
     */
    async function generateMarketingArt(id) {
        return confirmPaidImage({
            title: 'Generate this artwork',
            note: 'This replaces any existing artwork on this asset and costs credits.',
            previewUrl: `/marketing/${id}/preview`,
            send: async choices => {
                setStatus('Generating artwork...', true);
                try {
                    const res = await api(`/marketing/${id}/generate`,
                        { method: 'POST', body: JSON.stringify(choices) });
                    setStatus(res.provider ? `Artwork generated via ${res.provider}.` : 'Artwork generated.');
                    loadMarketing();
                } catch (err) { setStatus('Could not generate: ' + err.message); }
            },
        });
    }

    async function deleteMarketingAsset(id) {
        if (!confirm('Delete this marketing asset? The artwork file stays on disk.')) return;
        try {
            await api('/marketing/' + id, { method: 'DELETE' });
            setStatus('Deleted');
            loadMarketing();
        } catch (err) { setStatus('Error: ' + err.message); }
    }
